 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    rectangles = set()
    # Enumerate maximal solid rectangles.  In this task the large blocks may
    # be short in one dimension, so use area rather than a fixed 5x5 cutoff.
    for top in range(h):
        for bottom in range(top, h):
            height = bottom - top + 1
            if height < 2:
                continue
            for color in range(10):
                valid = [all(grid[r][c] == color for r in range(top, bottom + 1)) for c in range(w)]
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    end = c
                    while end < w and valid[end]:
                        end += 1
                    width = end - c
                    if width >= 2 and height * width >= 12:
                        # Keep only vertically maximal rectangles. Runs are
                        # already horizontally maximal for this row interval.
                        can_extend_up = top > 0 and all(grid[top - 1][x] == color for x in range(c, end))
                        can_extend_down = bottom + 1 < h and all(grid[bottom + 1][x] == color for x in range(c, end))
                        if not can_extend_up and not can_extend_down:
                            rectangles.add((top, bottom, c, end - 1))
                    c = end
    out = [row[:] for row in grid]
    for top, bottom, left, right in rectangles:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = 4
    return out
