{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = [[False] * w for _ in range(h)]
    # Locate maximal solid monochromatic rectangles. Patches in the examples
    # have at least four rows and five columns (the smallest is 4x5).
    for top in range(h):
        for bottom in range(top + 3, h):
            height = bottom - top + 1
            for color in range(10):
                valid = [all(grid[r][c] == color for r in range(top, bottom + 1)) for c in range(w)]
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    end = c
                    while end < w and valid[end]:
                        end += 1
                    width = end - c
                    if width >= 5 and height * width >= 20:
                        # Reject sub-rectangles: preserve only rectangles that
                        # cannot be extended vertically across their full width.
                        extends_up = top > 0 and all(grid[top - 1][x] == color for x in range(c, end))
                        extends_down = bottom + 1 < h and all(grid[bottom + 1][x] == color for x in range(c, end))
                        if not extends_up and not extends_down:
                            for r in range(top, bottom + 1):
                                for x in range(c, end):
                                    marked[r][x] = True
                    c = end
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
