 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = [[False] * w for _ in range(h)]
    # Large solid monochromatic panels are replaced with color 4. A panel is
    # at least 4 rows by 5 columns (area 20); runs are intersected over each
    # row interval so the whole solid rectangle is found despite noisy edges.
    for top in range(h):
        for bottom in range(top + 3, h):
            height = bottom - top + 1
            for color in range(10):
                valid = [all(grid[r][c] == color for r in range(top, bottom + 1))
                         for c in range(w)]
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    end = c + 1
                    while end < w and valid[end]:
                        end += 1
                    width = end - c
                    if width >= 5 and height * width >= 20:
                        for r in range(top, bottom + 1):
                            for x in range(c, end):
                                marked[r][x] = True
                    c = end
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
